SELECT  FROM ddc_config_item c
WHERE c.tenant_id = #{tenantId} AND c.biz_code = #{bizCode} AND c.env = #{env}
  AND c.app_code = #{appCode} AND c.config_key = #{resourceName} AND c.deleted_at IS NULL

SELECT count(*) FROM ddc_config_item c
WHERE c.tenant_id = #{tenantId} AND c.biz_code = #{bizCode} AND c.app_code = #{appCode}
  AND c.deleted_at IS NULL

mapper.sql:
c.tenant_id = #{tenantId} AND c.deleted_at IS NULL
AND c.biz_code = #{bizCode}
AND c.env = #{env}
AND c.app_code = #{appCode}

    AND c.config_key LIKE concat('%', #{resourceName}, '%')

AND c.deleted = false

    AND EXISTS (
        SELECT 1
        FROM ddc_namespace_env_app b
        JOIN ddc_namespace n ON n.tenant_id = b.tenant_id AND n.id = b.namespace_id
        JOIN ddc_app a ON a.tenant_id = b.tenant_id AND a.id = b.app_id
        WHERE b.tenant_id = c.tenant_id AND b.deleted_at IS NULL AND b.enabled = true
          AND n.deleted_at IS NULL AND n.enabled = true AND n.namespace_code = #{namespaceCode}
          AND n.biz_code = c.biz_code AND a.biz_code = c.biz_code AND a.app_code = c.app_code
          AND b.env_code = c.env
    )

mapper.update:
UPDATE ddc_config_item
   SET deleted_at = CURRENT_TIMESTAMP AT TIME ZONE 'UTC',
       version = version + 1,
       update_user_id = #{et.updateUserId},
       update_time = #{et.updateTime}
 WHERE tenant_id = #{et.tenantId}
   AND id = #{et.id}
   AND version = #{et.version}
   AND deleted_at IS NULL
